1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.util.CheckDigit;
10	import org.springframework.samples.petclinic.util.FiscalYear;
11	import org.springframework.samples.petclinic.util.LocalityResolver;
12	import org.springframework.samples.petclinic.util.Sha256Hash;
13	
14	/**
15	 * Assigns the owner's {@code memberId} before it is saved. It unifies the former
16	 * {@code customerCode} and {@code membershipNumber} into a single value formatted
17	 * {@code <REGION><FY><HASH8><CHK>}, where:
18	 *
19	 * <ul>
20	 * <li>{@code REGION} is the region code derived from the postcode (see {@link LocalityResolver});</li>
21	 * <li>{@code FY} is the last two digits of the fiscal year (starting 1 July) of the
22	 * business-day-adjusted {@code registrationDate}, zero-padded;</li>
23	 * <li>{@code HASH8} is the first 8 upper-case hex characters of SHA-256 over the concatenation of
24	 * the normalized telephone and the last name (the same HASH8 used by the region-and-hash identity);
25	 * and</li>
26	 * <li>{@code CHK} is a single Luhn check digit computed over the digits of
27	 * {@code <REGION><FY><HASH8>} (see {@link CheckDigit}).</li>
28	 * </ul>
29	 *
30	 * (e.g. {@code NSW273F1A9C2B4}.) The telephone was normalized to E.164 by {@link ValidateNewOwner},
31	 * so {@code owner.getTelephone()} is already the normalized value, and {@link BuildOwner} has set the
32	 * business-day-adjusted {@code registrationDate}.
33	 *
34	 * <p>Should the computed id collide with an existing owner's {@code memberId}, it is de-duplicated by
35	 * appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique
36	 * (e.g. {@code NSW273F1A9C2B4-2}). Runs after {@link BuildOwner} and before {@link SaveOwner}, so
37	 * {@link OwnerRepository#findAll()} returns only the pre-existing owners. Mutates the entity in place
38	 * so {@link SaveOwner} persists it.
39	 */
40	public class AssignMemberId {
41	
42	    /** Number of upper-case hex characters taken from the SHA-256 digest. */
43	    private static final int HASH_LENGTH = 8;
44	
45	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
46	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
47	        String fy = String.format("%02d", FiscalYear.yearOf(owner.getRegistrationDate()) % 100);
48	        String hash8 = Sha256Hash.upperHex(owner.getTelephone() + owner.getLastName(), HASH_LENGTH);
49	        String body = region + fy + hash8;
50	        String baseId = body + CheckDigit.luhnOf(body);
51	
52	        Set<String> existingIds = new HashSet<>();
53	        for (Owner other : ownerRepository.findAll()) {
54	            existingIds.add(other.getMemberId());
55	        }
56	
57	        String memberId = baseId;
58	        for (int n = 2; existingIds.contains(memberId); n++) {
59	            memberId = baseId + "-" + n;
60	        }
61	        owner.setMemberId(memberId);
62	    }
63	}
