1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Derives an owner's {@code ownerSegment}, a marketing segment formatted {@code "<TIER>_<AREA>"}.
5	 *
6	 * <p>{@code TIER} is {@code "PREMIUM"} when the owner's {@code membershipLevel} is
7	 * {@value #PREMIUM_LEVEL} or more, otherwise {@code "STANDARD"}. {@code AREA} is {@code "METRO"}
8	 * when the owner's locality is a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}.
9	 * The four possible values are {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
10	 * {@code STANDARD_METRO} and {@code STANDARD_REGIONAL}.
11	 */
12	public final class OwnerSegment {
13	
14	    /** Membership level at or above which the tier is {@code "PREMIUM"}. */
15	    private static final int PREMIUM_LEVEL = 3;
16	
17	    private OwnerSegment() {
18	    }
19	
20	    /** The segment {@code "<TIER>_<AREA>"} for {@code membershipLevel} and {@code locality}. */
21	    public static String of(int membershipLevel, String locality) {
22	        String tier = membershipLevel >= PREMIUM_LEVEL ? "PREMIUM" : "STANDARD";
23	        String area = LocalityResolver.isKnownRegion(locality) ? "METRO" : "REGIONAL";
24	        return tier + "_" + area;
25	    }
26	}
