3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Immutable structured audit event emitted alongside the human-readable audit line when a new owner
9	 * is created (see {@link AuditOwnerCreated}). Serialized to a single-line JSON object
10	 * {@code {seq, ownerId, memberId, membershipLevel, event}} where {@code event} is always
11	 * {@value #EVENT}.
12	 *
13	 * <p>{@code seq} is a process-wide, monotonically increasing sequence number handed out by
14	 * {@link #of(Owner, int)} — one per created owner, ordering the events regardless of which request
15	 * produced them.
16	 *
17	 * <p>The event carries the owner's <em>current primary identifier</em>, resolved once by
18	 * {@link #primaryIdentifierOf(Owner)} — the unified {@code memberId}.
19	 *
20	 * <p>Instances are immutable: all fields are captured at construction and never mutated.
21	 */
22	final class OwnerCreatedEvent {
23	
24	    /** The fixed {@code event} discriminator carried by every owner-created event. */
25	    static final String EVENT = "OWNER_CREATED";
26	
27	    /** Process-wide source of monotonically increasing sequence numbers across all creates. */
28	    private static final AtomicLong SEQUENCE = new AtomicLong();
29	
30	    private final long seq;
31	
32	    private final int ownerId;
33	
34	    private final String primaryIdentifier;
35	
36	    private final int membershipLevel;
37	
38	    private OwnerCreatedEvent(long seq, int ownerId, String primaryIdentifier, int membershipLevel) {
39	        this.seq = seq;
40	        this.ownerId = ownerId;
41	        this.primaryIdentifier = primaryIdentifier;
42	        this.membershipLevel = membershipLevel;
43	    }
44	
45	    /**
46	     * A new event for the just-saved {@code owner} at the given {@code membershipLevel}, drawing the
47	     * next sequence number. The owner must already be persisted so {@link Owner#getId()} is set.
48	     */
49	    static OwnerCreatedEvent of(Owner owner, int membershipLevel) {
50	        return new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
51	                primaryIdentifierOf(owner), membershipLevel);
52	    }
53	
54	    /**
55	     * The owner's current primary identifier. This is the single point that decides which field
56	     * value the event carries: the unified {@code memberId}.
57	     */
58	    private static String primaryIdentifierOf(Owner owner) {
59	        return owner.getMemberId();
60	    }
61	
62	    /** This event as a compact, single-line JSON object. */
63	    String toJson() {
64	        return "{"
65	                + "\"seq\":" + this.seq
66	                + ",\"ownerId\":" + this.ownerId
67	                + ",\"memberId\":" + quote(this.primaryIdentifier)
68	                + ",\"membershipLevel\":" + this.membershipLevel
69	                + ",\"event\":" + quote(EVENT)
70	                + "}";
71	    }
72	
73	    /** JSON string literal for {@code value}, escaping quotes and backslashes, or {@code null}. */
74	    private static String quote(String value) {
75	        if (value == null) {
76	            return "null";
77	        }
78	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
79	        for (int i = 0; i < value.length(); i++) {
80	            char c = value.charAt(i);
81	            if (c == '"' || c == '\\') {
82	                sb.append('\\');
83	            }
84	            sb.append(c);
85	        }
86	        return sb.append('"').toString();
87	    }
88	}
