8	
9	/**
10	 * The duplicate-detection step of {@code POST /api/owners}. Duplicate detection is the single
11	 * {@code identityKey} (see {@link OwnerIdentityKey}): a request is a duplicate only when an existing
12	 * owner carries the <em>same whole key</em> — normalized telephone, email and {@code soundex(lastName)}
13	 * all equal. There is no separate household-duplicate block: the postcode is not part of the key, so
14	 * two owners with the same last name and postcode but different telephones have different keys and are
15	 * both allowed (the weaker overlap is a soft match, see {@link AssignPossibleDuplicate}); only a
16	 * genuine re-submission of the same owner is rejected with 409.
17	 *
18	 * <p>The email-domain blocklist is applied earlier, in {@link ValidateNewOwner}, so a disposable
19	 * domain is a 400 before this step runs. Soft-deleted owners are ignored here.
20	 *
21	 * <p>The {@code sharesHousehold} hint bypasses this block: a request that declares itself a member
22	 * of a shared household is allowed through and created as a legitimate second member (and is not
23	 * flagged as a possible duplicate, see {@link AssignPossibleDuplicate}).
24	 *
25	 * <p>Runs after {@link ValidateNewOwner} has normalized the request and before {@link BuildOwner},
26	 * so a duplicate is a 409 rather than a persisted record.
27	 */
28	public class CheckOwnerIdentityUnique {
29	
30	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
31	            throws DuplicateOwnerIdentityException {
32	        if (Household.sharesHousehold(request)) {
33	            return; // declared household member: bypass the duplicate block
34	        }
35	        String identityKey = OwnerIdentityKey.forRequest(request);
36	        for (Owner owner : ownerRepository.findAll()) {
37	            if (owner.isDeleted()) {
38	                continue; // a soft-deleted owner no longer blocks a new create
39	            }
40	            if (identityKey.equals(OwnerIdentityKey.forOwner(owner))) {
41	                throw new DuplicateOwnerIdentityException(Household.idFor(request));
42	            }
43	        }
44	    }
45	}
