3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * SHA-256 helper for deriving short, stable identifiers. Hashes the UTF-8 bytes of the input and
9	 * exposes the leading hex characters in upper case, as used by the owner {@code memberId}
10	 * (its {@code HASH8} component is the first 8 upper-case hex characters of SHA-256).
11	 */
12	public final class Sha256Hash {
13	
14	    private Sha256Hash() {
15	    }
16	
17	    /** The first {@code n} UPPER-case hex characters of SHA-256 over the UTF-8 bytes of {@code s}. */
18	    public static String upperHex(String s, int n) {
19	        byte[] digest = digest(s);
20	        StringBuilder sb = new StringBuilder(n);
21	        for (int i = 0; i < digest.length && sb.length() < n; i++) {
22	            sb.append(String.format("%02X", digest[i]));
23	        }
24	        return sb.substring(0, n);
25	    }
26	
27	    private static byte[] digest(String s) {
28	        try {
29	            return MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
30	        }
31	        catch (NoSuchAlgorithmException ex) {
32	            throw new IllegalStateException("SHA-256 not available", ex);
33	        }
34	    }
35	}
