5	 * {@code CHK} segment of an owner's {@code memberId}, computed over the digits of
6	 * {@code <REGION><FY><HASH8>}. Non-digit characters (the letters of a value such as
7	 * {@code NSW273F1A9C2B}) are skipped, and the standard Luhn algorithm is applied to the remaining
8	 * digits, doubling every second digit from the right.
9	 */
10	public final class CheckDigit {
11	
12	    private CheckDigit() {
13	    }
14	
15	    /**
16	     * Returns the Luhn check digit (0-9) over the digits contained in {@code code}, or
17	     * {@code null} when {@code code} is {@code null}.
18	     */
19	    public static Integer luhnOf(String code) {
20	        if (code == null) {
21	            return null;
22	        }
23	        int sum = 0;
24	        boolean dbl = true;
25	        for (int i = code.length() - 1; i >= 0; i--) {
26	            char c = code.charAt(i);
27	            if (c < '0' || c > '9') {
28	                continue;
29	            }
30	            int d = c - '0';
31	            if (dbl) {
32	                d *= 2;
33	                if (d > 9) {
34	                    d -= 9;
35	                }
36	            }
37	            sum += d;
38	            dbl = !dbl;
39	        }
40	        return (10 - (sum % 10)) % 10;
41	    }
42	}
