1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Standard American (Russell/NARA) Soundex encoding of a surname: the first letter followed by three
5	 * digits summarising the remaining consonant sounds, so that names that sound alike share a code
6	 * (e.g. {@code Smith} and {@code Smyth} both encode to {@code S530}).
7	 *
8	 * <p>Used by {@link OwnerIdentityKey} (as the last-name component of an owner's identity key) and by
9	 * {@link AssignPossibleDuplicate} (which flags a soft match when two owners share a Soundex code and
10	 * postcode but differ in their identity key).
11	 *
12	 * <p>Rules: retain the first letter; map the rest to digits — {@code b,f,p,v}→1;
13	 * {@code c,g,j,k,q,s,x,z}→2; {@code d,t}→3; {@code l}→4; {@code m,n}→5; {@code r}→6; vowels and
14	 * {@code y} do not code and separate consonants (same-coded consonants split by a vowel are coded
15	 * twice), while {@code h} and {@code w} are transparent (same-coded consonants split by them are
16	 * coded once). Adjacent identical codes collapse to one. The result is padded with zeros or truncated
17	 * to exactly four characters.
18	 */
19	final class Soundex {
20	
21	    private Soundex() {
22	    }
23	
24	    /** The four-character Soundex code of {@code name}, or empty when it contains no letters. */
25	    static String soundex(String name) {
26	        if (name == null) {
27	            return "";
28	        }
29	        StringBuilder letters = new StringBuilder();
30	        for (int i = 0; i < name.length(); i++) {
31	            char c = name.charAt(i);
32	            if (Character.isLetter(c)) {
33	                letters.append(Character.toUpperCase(c));
34	            }
35	        }
36	        if (letters.length() == 0) {
37	            return "";
38	        }
39	        StringBuilder code = new StringBuilder(4);
40	        code.append(letters.charAt(0));
41	        char prev = codeOf(letters.charAt(0));
42	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
43	            char c = letters.charAt(i);
44	            char digit = codeOf(c);
45	            if (digit != '0' && digit != prev) {
46	                code.append(digit);
47	            }
48	            // 'h' and 'w' are transparent: keep the previous code so consonants they separate merge.
49	            if (c != 'H' && c != 'W') {
50	                prev = digit;
51	            }
52	        }
53	        while (code.length() < 4) {
54	            code.append('0');
55	        }
56	        return code.toString();
57	    }
58	
59	    private static char codeOf(char c) {
60	        switch (c) {
61	            case 'B': case 'F': case 'P': case 'V':
62	                return '1';
63	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
64	                return '2';
65	            case 'D': case 'T':
66	                return '3';
67	            case 'L':
68	                return '4';
69	            case 'M': case 'N':
70	                return '5';
71	            case 'R':
72	                return '6';
73	            default: // A, E, I, O, U, Y, H, W
74	                return '0';
75	        }
76	    }
77	}
